mapper.select:
SELECT pc.id, pd.id AS skuId, pd.images_url, pd.sku_no, pc.country, pc.country_name as countryName, pc.to_declare_price as toDeclarePrice, pc.to_currency as toCurrency, pc.to_currency_symbol as toCurrencySymbol, pc.customs_code, pc.tax_rate, pc.type FROM product_customs pc LEFT JOIN product_detail pd ON pc.sku_id = pd."id" AND pd.is_deleted = FALSE WHERE pc.is_deleted = FALSE and pc.sku_id in
#{item}
ORDER BY pc.update_time

select id,sku_id,country,customs_code,tax_rate,type, country_name, to_declare_price, to_currency, to_currency_symbol from product_customs where is_deleted = FALSE
and sku_id in
#{item}

mapper.sql:
SELECT pc.ID AS ID, pc.create_user_id AS createUserId, pc.create_user_name AS createUserName, pc.create_time AS createTime, pc.update_user_id AS updateUserId, pc.update_user_name AS updateUserName, pc.update_time AS updateTime, pc.VERSION AS VERSION, pc.is_deleted AS isDeleted, pd.ID AS skuId, pd.sku_no AS skuNo, pd.images_url AS imagesUrl, pl.declare_chinese_name AS declareChineseName, pl.customs_code AS chinaCustomsCode, pc.to_declare_price AS destDeclarePrice, pc.to_currency AS destCurrency, pc.to_currency_symbol AS destCurrencySymbol, pc.customs_code AS destinationCustomsCode, pc.tax_rate as taxRate, pc.destination_vat_rate as destinationVatRate, pc.destination_additional_duty_rate as destinationAdditionalDutyRate, pc.destination_anti_dumping_duty_rate as destinationAntiDumpingDutyRate, pc.destination_other_tax_rate as destinationOtherTaxRate, pc.TYPE, pl.declare_model as declareModel, pl.declare_element as declareElement FROM product_customs pc LEFT JOIN product_detail pd ON pc.sku_id = pd.ID AND pd.is_deleted = FALSE LEFT JOIN product_info pi ON pi.ID = pd.product_id AND pi.is_deleted = FALSE LEFT JOIN product_logistics pl ON pl.sku_id = pc.sku_id AND pl.is_deleted = FALSE WHERE ${params.sqlMap.default} and pc.is_deleted = FALSE and pc.type = 'clearanceCustoms'
and pc.id in
#{id}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
pc.create_time DESC
